===BEGIN llm_candidates.jsonl===
{"title":"Beyond Factual Accuracy: Evaluating Coverage of Diverse Factual Information in Long-form Text Generation","url":"https://arxiv.org/abs/2501.03545","arxiv_id":"2501.03545","doi":"10.18653/v1/2025.findings-acl.693","authors":["Chris Samarinas","Alexander Krubner","Alireza Salemi","Youngwoo Kim","Hamed Zamani"],"year":2025,"published":"2025-01-07","abstract":"Introduces ICAT for evaluating whether long-form generation covers diverse expected factual information, using atomic-claim decomposition, retrieval-based verification, and alignment of generated claims to expected aspects.","venue":"Findings of ACL 2025"}
{"title":"Fact in Fragments: Deconstructing Complex Claims via LLM-based Atomic Fact Extraction and Verification","url":"https://arxiv.org/abs/2506.07446","arxiv_id":"2506.07446","doi":"10.1016/j.eswa.2025.130572","authors":["Liwen Zheng","Chaozhuo Li","Zheng Liu","Feiran Huang","Haoran Jia","Zaisheng Ye","Xi Zhang"],"year":2025,"published":"2025-06-09","abstract":"Presents a framework that iteratively decomposes complex claims into atomic facts, retrieves and reranks evidence, and verifies the resulting facts, including cases where support is fragmented across evidence.","venue":"Expert Systems with Applications"}
{"title":"Investigating Factuality in Long-Form Text Generation: The Roles of Self-Known and Self-Unknown","url":"https://arxiv.org/abs/2411.15993","arxiv_id":"2411.15993","authors":["Lifu Tu","Rui Meng","Shafiq Joty","Yingbo Zhou","Semih Yavuz"],"year":2024,"published":"2024-11-24","abstract":"Studies factuality at the atomic-claim level in long-form generation and examines whether models can distinguish claims they know from claims they do not know, connecting claim support with uncertainty behavior.","venue":"arXiv"}
{"title":"Atomic Contrastive Verification: Fine-Grained Fact-Checking via Claim Decomposition and Knowledge Graph-Grounded Contrastive Reasoning","url":"https://www.mdpi.com/2227-7390/14/10/1769","doi":"10.3390/math14101769","authors":["Hyeong-Geun Kim","Tea-Sung Jun","Taeseon Lee"],"year":2026,"published":"2026-05-21","abstract":"Decomposes text into atomic claims and applies knowledge-graph-grounded contrastive reasoning for fine-grained verification, including contradictions and temporal distortions that sentence-level scoring can obscure.","venue":"Mathematics"}
{"title":"Optimizing Decomposition for Optimal Claim Verification","url":"https://arxiv.org/abs/2503.15354","arxiv_id":"2503.15354","doi":"10.18653/v1/2025.acl-long.254","authors":["Yining Lu","Noah Ziems","Hy Dang","Meng Jiang"],"year":2025,"published":"2025-03-19","abstract":"Studies how claim decomposition affects downstream verification and proposes dynamically adapting decomposition using verifier feedback rather than assuming a fixed notion of atomicity.","venue":"ACL 2025"}
{"title":"Decomposition Dilemmas: Does Claim Decomposition Boost or Burden Fact-Checking Performance?","url":"https://arxiv.org/abs/2411.02400","arxiv_id":"2411.02400","doi":"10.18653/v1/2025.naacl-long.320","authors":["Qisheng Hu","Quanyu Long","Wenya Wang"],"year":2025,"abstract":"Analyzes when decompose-then-verify pipelines help or hurt fact checking, including decomposition errors and the trade-off between simpler subclaims and loss or distortion of information.","venue":"NAACL 2025"}
{"title":"Complex Claim Verification with Evidence Retrieved in the Wild","url":"https://arxiv.org/abs/2305.11859","arxiv_id":"2305.11859","doi":"10.18653/v1/2024.naacl-long.196","authors":["Jifan Chen","Grace Kim","Aniruddh Sriram","Greg Durrett","Eunsol Choi"],"year":2024,"published":"2023-05-19","abstract":"Builds a complex-claim verification pipeline combining claim decomposition, web retrieval, fine-grained evidence selection, evidence summarization, and final veracity prediction, while examining incompleteness in retrieved evidence.","venue":"NAACL 2024"}
{"title":"A Claim Decomposition Benchmark for Long-Form Answer Verification","url":"https://arxiv.org/abs/2410.12558","arxiv_id":"2410.12558","doi":"10.1007/978-981-96-1710-4_4","authors":["Zhihao Zhang","Yixing Fan","Ruqing Zhang","Jiafeng Guo"],"year":2024,"published":"2024-10-16","abstract":"Introduces a benchmark for decomposing long-form answers into atomic claims suitable for independent verification, enabling evaluation below the sentence level.","venue":"CCIR 2024"}
{"title":"FACTS&EVIDENCE: An Interactive Tool for Transparent Fine-Grained Factual Verification of Machine-Generated Text","url":"https://arxiv.org/abs/2503.14797","arxiv_id":"2503.14797","doi":"10.18653/v1/2025.naacl-demo.35","authors":["Varich Boonsanong","Vidhisha Balachandran","Xiaochuang Han","Shangbin Feng","Lucy Lu Wang","Yulia Tsvetkov"],"year":2025,"published":"2025-03-19","abstract":"Provides interactive fine-grained verification by breaking generated text into claims, retrieving multiple evidence sources, and exposing evidence and explanations so users can inspect attribution and support.","venue":"NAACL 2025 Demonstrations"}
{"title":"ToE: A Hierarchical and Explainable Claim Verification Framework with Dynamic Multi-source Evidence Retrieval and Aggregation","url":"https://arxiv.org/abs/2606.27736","arxiv_id":"2606.27736","authors":["Zhaoqi Wang","Zijian Zhang","Kun Zheng","Zhen Li","Xin Li","Chunlei Li","Jiamou Liu"],"year":2026,"published":"2026-06-26","abstract":"Uses a hierarchical argument tree with iterative decomposition, dynamic multi-source retrieval, evidence evaluation, aggregation, and verification to handle complex claims requiring evidence from multiple sources.","venue":"arXiv"}
{"title":"Fact Checking with Insufficient Evidence","url":"https://arxiv.org/abs/2204.02007","arxiv_id":"2204.02007","doi":"10.1162/tacl_a_00486","authors":["Pepa Atanasova","Jakob Grue Simonsen","Christina Lioma","Isabelle Augenstein"],"year":2022,"published":"2022-04-05","abstract":"Studies whether available evidence is sufficient for fact verification and develops diagnostics based on removing evidence constituents or sentences, separating evidence sufficiency from the final veracity decision.","venue":"Transactions of the Association for Computational Linguistics"}
{"title":"RealRoute: Dynamic Query Routing System via Retrieve-then-Verify Paradigm","url":"https://arxiv.org/abs/2604.20860","arxiv_id":"2604.20860","authors":["Jiahe Liu","Qinkai Yu","Jingcheng Niu","Xi Zhu","Zirui He","Zhen Xiang","Fan Yang","Jinman Zhao"],"year":2026,"abstract":"Proposes source-agnostic parallel retrieval followed by verification and dynamic routing across heterogeneous information sources, targeting evidence completeness and multi-hop questions rather than relying on one retrieval pass.","venue":"arXiv"}
{"title":"Evidence-Based Temporal Fact Verification","url":"https://arxiv.org/abs/2407.15291","arxiv_id":"2407.15291","authors":["Anab Maulana Barik","Wynne Hsu","Mong Li Lee"],"year":2024,"published":"2024-07-21","abstract":"Develops an end-to-end temporal fact-verification approach that models events and time-sensitive evidence so claim validity can be assessed with respect to temporal context rather than as a timeless fact.","venue":"arXiv"}
{"title":"TSVer: A Benchmark for Fact Verification Against Time-Series Evidence","url":"https://arxiv.org/abs/2511.01101","arxiv_id":"2511.01101","doi":"10.18653/v1/2025.emnlp-main.1519","authors":["Marek Strong","Andreas Vlachos"],"year":2025,"published":"2025-11-02","abstract":"Introduces a benchmark in which real-world claims must be verified against time-series evidence, with annotations covering relevant time frames, verdicts, and justifications.","venue":"EMNLP 2025"}
{"title":"Towards Understanding Omission in Dialogue Summarization","url":"https://arxiv.org/abs/2211.07145","arxiv_id":"2211.07145","doi":"10.18653/v1/2023.acl-long.798","authors":["Yicheng Zou","Kaitao Song","Xu Tan","Zhongkai Fu","Qi Zhang","Dongsheng Li","Tao Gui"],"year":2023,"published":"2022-11-14","abstract":"Introduces explicit omission annotations and an omission-detection task for dialogue summaries, evaluating which important source information is absent from generated summaries rather than only measuring overall similarity or faithfulness.","venue":"ACL 2023"}
{"title":"Detecting Omissions in LLM-Generated Medical Summaries","url":"https://aclanthology.org/2025.emnlp-industry.22/","doi":"10.18653/v1/2025.emnlp-industry.22","authors":["Achir Oukelmoun","Nasredine Semmar","Gaël de Chalendar","Clement Cormi","Mariame Oukelmoun","Eric Vibert","Marc-Antoine Allard"],"year":2025,"abstract":"Studies detection of clinically important information omitted from LLM-generated medical summaries and proposes a reference-free method for identifying such omissions.","venue":"EMNLP 2025 Industry Track"}
{"title":"Mitigating Hallucinations in Healthcare LLMs with Granular Fact-Checking and Domain-Specific Adaptation","url":"https://arxiv.org/abs/2512.16189","arxiv_id":"2512.16189","doi":"10.1016/j.eswa.2026.132966","authors":["Musarrat Zeba","Abdullah Al Mamun","Kishoar Jahan Tithee","Debopom Sutradhar","Mohaimenul Azam Khan Raiaan","Saddam Mukta","Reem E. Mohamed","Md Rafiqul Islam","Yakub Sebastian","Mukhtar Hussain","Sami Azam"],"year":2026,"abstract":"Uses granular proposition mapping and checks for negation, implication, temporal, numerical, and semantic consistency against clinical records, together with presence checks intended to expose omitted information.","venue":"Expert Systems with Applications"}
{"title":"Unsupervised update summarization of news events","url":"https://www.sciencedirect.com/science/article/pii/S003132032300537X","doi":"10.1016/j.patcog.2023.109839","authors":["Florian Carichon","Florent Fettu","Gilles Caporossi"],"year":2023,"abstract":"Presents unsupervised incremental summarization for evolving events, emphasizing novelty, cohesion, and information updates so later summaries avoid simply repeating earlier material.","venue":"Pattern Recognition"}
{"title":"Incremental Update Summarization: Adaptive Sentence Selection based on Prevalence and Novelty","url":"https://eprints.gla.ac.uk/101448/","doi":"10.1145/2661829.2661951","authors":["Richard McCreadie","Craig Macdonald","Iadh Ounis"],"year":2014,"abstract":"Studies incremental summarization of evolving streams and adaptively selects updates using prevalence and novelty, explicitly addressing redundancy and information that becomes outdated as events develop.","venue":"CIKM 2014"}
{"title":"Mining Sequential Update Summarization with Hierarchical Text Analysis","url":"https://onlinelibrary.wiley.com/doi/10.1155/2016/1340973","doi":"10.1155/2016/1340973","year":2016,"abstract":"Addresses sequential update summarization for evolving information streams using hierarchical text analysis and evaluates update quality with temporal-summarization measures including comprehensiveness and latency-sensitive gain.","venue":"Mobile Information Systems"}
{"title":"TREC 2015 Temporal Summarization Track Overview","url":"https://pages.nist.gov/trec-browser/trec24/tempsumm/overview/","doi":"10.6028/NIST.SP.500-319.tempsumm-overview","authors":["Javed A. Aslam","Fernando Diaz","Matthew Ekstrand-Abueg","Richard McCreadie","Virgil Pavlu","Tetsuya Sakai"],"year":2015,"abstract":"Describes evaluation of online temporal summarization for evolving events, including nugget-based comprehensiveness together with novelty, usefulness, and timeliness of successive updates.","venue":"TREC 2015"}
{"title":"The Information Extraction Systems of PRIS at Temporal Summarization Track","url":"https://pages.nist.gov/trec-browser/trec22/tempsumm/proceedings/","doi":"10.6028/NIST.SP.500-302.tempsumm-PRIS","authors":["Chunyun Zhang","Weiyan Xu","Fanyu Meng","Hongyan Li","Tong Wu","Lixin Xu"],"year":2013,"abstract":"Describes systems for the TREC Temporal Summarization tasks, including sequential update summarization and value tracking of attributes whose reported values can change over time.","venue":"TREC 2013"}
{"title":"CLIN-SUMM: Incremental Longitudinal Summarization of Clinical Notes Enables Scalable Representation and Early Disease Prediction","url":"https://www.medrxiv.org/content/10.64898/2025.11.28.25341233v2","doi":"10.64898/2025.11.28.25341233","authors":["Valentina D’Souza","Danielle F. Pace","Alaleh Azhir","Arash Nargesi","Erik B. Holbrook","Wei He","Tristan Naumann","Samuel Friedman","Steven J. Atlas","Christopher D. Anderson","Judy Hung","Mahnaz Maddah"],"year":2025,"abstract":"Constructs longitudinal patient representations incrementally, summarizing newly documented information at each encounter while preserving temporal ordering and avoiding future information leakage.","venue":"medRxiv"}
{"title":"Selective Question Answering under Domain Shift","url":"https://arxiv.org/abs/2006.09462","arxiv_id":"2006.09462","doi":"10.18653/v1/2020.acl-main.503","authors":["Amita Kamath","Robin Jia","Percy Liang"],"year":2020,"published":"2020-06-16","abstract":"Studies selective question answering when deployment mixes in-domain and shifted examples, using a calibrator to decide which answers to return and evaluating error as coverage changes.","venue":"ACL 2020"}
{"title":"The Art of Abstention: Selective Prediction and Error Regularization for Natural Language Processing","url":"https://aclanthology.org/2021.acl-long.84/","doi":"10.18653/v1/2021.acl-long.84","authors":["Ji Xin","Raphael Tang","Yaoliang Yu","Jimmy Lin"],"year":2021,"abstract":"Studies selective prediction for NLP, compares confidence estimators used for abstention, and introduces error regularization to improve the relationship between retained coverage and prediction risk.","venue":"ACL-IJCNLP 2021"}
{"title":"Selective Classification for Deep Neural Networks","url":"https://arxiv.org/abs/1705.08500","arxiv_id":"1705.08500","authors":["Yonatan Geifman","Ran El-Yaniv"],"year":2017,"published":"2017-05-23","abstract":"Develops selective classifiers for deep networks that can reject predictions to meet a desired risk level with high probability and evaluates performance through the risk-coverage trade-off.","venue":"NeurIPS 2017"}
{"title":"SelectiveNet: A Deep Neural Network with an Integrated Reject Option","url":"https://arxiv.org/abs/1901.09192","arxiv_id":"1901.09192","authors":["Yonatan Geifman","Ran El-Yaniv"],"year":2019,"published":"2019-01-26","abstract":"Introduces an end-to-end neural architecture that jointly learns prediction and selection, directly optimizing performance at a target coverage rather than adding rejection only after training.","venue":"ICML 2019"}
{"title":"Classification Methods with Reject Option Based on Convex Risk Minimization","url":"https://www.jmlr.org/papers/v11/yuan10a.html","authors":["Ming Yuan","Marten Wegkamp"],"year":2010,"abstract":"Develops binary classification with a reject option using convex surrogate risks and establishes consistency and excess-risk results for decision rules that may abstain when classification is insufficiently reliable.","venue":"Journal of Machine Learning Research"}
{"title":"Optimal Strategies for Reject Option Classifiers","url":"https://www.jmlr.org/papers/v24/21-0048.html","authors":["Vojtech Franc","Daniel Prusa","Vaclav Voracek"],"year":2023,"abstract":"Provides a unified treatment of reject-option classification under cost-based, bounded-improvement, and bounded-abstention formulations, including optimal strategies connecting selective risk and achievable coverage.","venue":"Journal of Machine Learning Research"}
{"title":"Selective Classification Under Distribution Shifts","url":"https://arxiv.org/abs/2405.05160","arxiv_id":"2405.05160","authors":["Hengyue Liang","Le Peng","Ju Sun"],"year":2024,"published":"2024-05-08","abstract":"Studies selective classification under label, covariate, and out-of-distribution shifts and evaluates confidence scores and rejection strategies when test distributions differ from training.","venue":"arXiv"}
{"title":"Selective classification under imbalance in multiclass settings: A novel metric for bias-aware risk–coverage evaluation","url":"https://www.sciencedirect.com/science/article/pii/S1532046426001085","doi":"10.1016/j.jbi.2026.105084","authors":["Fatih Sağlam","Ünsal Özgen","Alper Uygun","Oğuz Salih Dinçer","Canan Albayrak"],"year":2026,"published":"2026-07-22","abstract":"Shows that aggregate risk-coverage evaluation can hide class-specific failures under imbalance and proposes class-aware measures and class-conditional rejection analysis.","venue":"Journal of Biomedical Informatics"}
{"title":"Conformal selective prediction with cost aware deferral for safe clinical triage under distribution shift","url":"https://www.nature.com/articles/s41598-026-40637-w","doi":"10.1038/s41598-026-40637-w","authors":["Hyun Kwon","Dae-Jin Kim"],"year":2026,"published":"2026-02-20","abstract":"Combines calibrated probabilistic prediction, conformal uncertainty sets, and cost-aware deferral, evaluating selective decisions and risk-coverage behavior on temporally separated in- and out-of-distribution clinical data.","venue":"Scientific Reports"}
{"title":"COIN: Uncertainty-Guarding Selective Question Answering for Foundation Models with Provable Risk Guarantees","url":"https://ojs.aaai.org/index.php/AAAI/article/view/40667","doi":"10.1609/aaai.v40i40.40667","authors":["Zhiyuan Wang","Jinhao Duan","Qingni Wang","Xiaofeng Zhu","Tianlong Chen","Xiaoshuang Shi","Kaidi Xu"],"year":2026,"abstract":"Develops uncertainty-aware selective question answering with statistical risk guarantees, using conformal techniques to control errors among answers that a foundation model elects to provide.","venue":"AAAI 2026"}
{"title":"Conformal Inference for Online Prediction with Arbitrary Distribution Shifts","url":"https://arxiv.org/abs/2208.08401","arxiv_id":"2208.08401","authors":["Isaac Gibbs","Emmanuel Candès"],"year":2022,"published":"2022-08-17","abstract":"Develops online conformal inference for sequences whose distributions may vary arbitrarily, using adaptive procedures and regret-style guarantees to respond to non-stationarity rather than assuming a fixed exchangeable stream.","venue":"arXiv"}
{"title":"Conformal Risk Control","url":"https://arxiv.org/abs/2208.02814","arxiv_id":"2208.02814","authors":["Anastasios N. Angelopoulos","Stephen Bates","Adam Fisch","Lihua Lei","Tal Schuster"],"year":2024,"published":"2022-08-04","abstract":"Generalizes conformal methods from set coverage to control of expected monotone loss, with extensions addressing distribution shift and other risk functions relevant to selective deployment.","venue":"ICLR 2024"}
{"title":"Score-Based Diffusion Priors for Adaptive Conformal Inference under Distribution Shift","url":"https://proceedings.mlr.press/v337/jiang26a.html","authors":["Xiangyu Jiang"],"year":2026,"abstract":"Combines adaptive conformal inference with score-based diffusion priors and online recalibration to improve coverage behavior under temporal and covariate distribution shifts.","venue":"UAI 2026"}
{"title":"Beyond conformal predictors: Adaptive Conformal Inference with confidence predictors","url":"https://www.sciencedirect.com/science/article/pii/S0031320325006594","doi":"10.1016/j.patcog.2025.111999","authors":["Johan Hallberg Szabadváry","Tuwe Löfström"],"year":2026,"abstract":"Studies adaptive conformal inference in non-exchangeable settings and incorporates confidence predictors to adapt uncertainty estimates as the data distribution changes.","venue":"Pattern Recognition"}
{"title":"Conformal prediction for labelling and updating online models in the presence of concept drift in cybersecurity","url":"https://www.sciencedirect.com/science/article/pii/S2214212625001577","doi":"10.1016/j.jisa.2025.104120","year":2025,"abstract":"Investigates conformal prediction as a mechanism for assigning labels and updating online models under concept drift, directly testing recalibration and model adaptation in a changing data stream.","venue":"Journal of Information Security and Applications"}
{"title":"Language Models (Mostly) Know What They Know","url":"https://arxiv.org/abs/2207.05221","arxiv_id":"2207.05221","year":2022,"published":"2022-07-11","abstract":"Evaluates whether language models can estimate the probability that their own answers are correct, including explicit probability-of-correctness and probability-of-knowing judgments on question-answering tasks.","venue":"arXiv"}
{"title":"Semantic Uncertainty: Linguistic Invariances for Uncertainty Estimation in Natural Language Generation","url":"https://arxiv.org/abs/2302.09664","arxiv_id":"2302.09664","authors":["Lorenz Kuhn","Yarin Gal","Sebastian Farquhar"],"year":2023,"published":"2023-02-19","abstract":"Introduces semantic entropy, which aggregates probability across semantically equivalent generations to estimate task-level uncertainty and predict whether free-form answers are likely to be correct.","venue":"arXiv"}
{"title":"Can LLMs Express Their Uncertainty? An Empirical Evaluation of Confidence Elicitation in LLMs","url":"https://proceedings.iclr.cc/paper_files/paper/2024/hash/6733cf15e10e2cd1d59af033c3bb8507-Abstract-Conference.html","authors":["Miao Xiong","Zhiyuan Hu","Xinyang Lu","Yifei Li","Jie Fu","Junxian He","Bryan Hooi"],"year":2024,"abstract":"Systematically evaluates methods for eliciting confidence from large language models, including verbalized confidence and sampling-based aggregation, and compares how well these estimates track answer correctness.","venue":"ICLR 2024"}
{"title":"VERIFICATION OF FORECASTS EXPRESSED IN TERMS OF PROBABILITY","url":"https://journals.ametsoc.org/view/journals/mwre/78/1/1520-0493_1950_078_0001_vofeit_2_0_co_2.xml","doi":"10.1175/1520-0493(1950)078<0001:VOFEIT>2.0.CO;2","authors":["Glenn W. Brier"],"year":1950,"published":"1950-01-01","venue":"Monthly Weather Review"}
{"title":"On optimum recognition error and reject tradeoff","url":"https://research.ibm.com/publications/on-optimum-recognition-error-and-reject-tradeoff","doi":"10.1109/TIT.1970.1054406","authors":["C. K. Chow"],"year":1970,"published":"1970-01-31","abstract":"Characterizes the trade-off between recognition error and rejection and derives an optimal rejection rule, providing a foundational decision-theoretic basis for selective prediction.","venue":"IEEE Transactions on Information Theory"}
{"title":"Humans or LLMs as the Judge? A Study on Judgement Biases","url":"https://arxiv.org/abs/2402.10669","arxiv_id":"2402.10669","doi":"10.18653/v1/2024.emnlp-main.474","authors":["Guiming Hardy Chen","Shunian Chen","Ziche Liu","Feng Jiang","Benyou Wang"],"year":2024,"published":"2024-02-16","abstract":"Compares human and LLM evaluators and investigates systematic judgment biases, showing that automatic judges can exhibit preferences unrelated to the intended evaluation construct.","venue":"EMNLP 2024"}
{"title":"Judging the Judges: A Systematic Study of Position Bias in LLM-as-a-Judge","url":"https://arxiv.org/abs/2406.07791","arxiv_id":"2406.07791","authors":["Lin Shi","Chiyu Ma","Wenhua Liang","Weicheng Ma","Soroush Vosoughi"],"year":2024,"published":"2024-06-12","abstract":"Systematically measures position bias in LLM judges and examines repetition stability, consistency, and fairness, demonstrating that evaluator outputs can depend on presentation order.","venue":"arXiv"}
{"title":"Go-Figure: A Meta Evaluation of Factuality in Summarization","url":"https://www.microsoft.com/en-us/research/publication/go-figure-a-meta-evaluation-of-factuality-in-summarization/","authors":["Saadia Gabriel","Asli Celikyilmaz","Rahul Jha","Yejin Choi","Jianfeng Gao"],"year":2021,"abstract":"Meta-evaluates factuality metrics using controlled diagnostic data and human judgments, testing whether automatic measures behave correctly under different factual-error conditions rather than relying on benchmark correlation alone.","venue":"ACL-IJCNLP 2021"}
{"title":"Are Factuality Checkers Reliable? Adversarial Meta-evaluation of Factuality in Summarization","url":"https://aclanthology.org/2021.findings-emnlp.179/","doi":"10.18653/v1/2021.findings-emnlp.179","authors":["Yiran Chen","Pengfei Liu","Xipeng Qiu"],"year":2021,"abstract":"Performs adversarial meta-evaluation of summarization factuality checkers on diagnostic datasets designed to expose specific weaknesses, showing that aggregate metric performance can hide systematic failure modes.","venue":"Findings of EMNLP 2021"}
{"title":"A Critical Look at Meta-evaluating Summarisation Evaluation Metrics","url":"https://arxiv.org/abs/2409.19507","arxiv_id":"2409.19507","authors":["Xiang Dai","Sarvnaz Karimi","Biaoyan Fang"],"year":2024,"published":"2024-09-29","abstract":"Critiques common meta-evaluation practice for summarization metrics, including narrow datasets and dimensions, and argues for more diverse, user-centered validation rather than treating a single correlation result as sufficient evidence.","venue":"arXiv"}
{"title":"Validating LLM-as-a-Judge Systems under Rating Indeterminacy","url":"https://www.microsoft.com/en-us/research/publication/validating-llm-as-a-judge-systems-under-rating-indeterminacy/","authors":["Luke Guerdan","Solon Barocas","Kenneth Holstein","Hanna Wallach","Zhiwei Steven Wu","Alex Chouldechova"],"year":2025,"abstract":"Studies validation of LLM judges when human ratings are intrinsically non-unique, showing why forced single-label comparisons can mischaracterize judge quality and motivating evaluation against sets or distributions of defensible human ratings.","venue":"NeurIPS 2025"}
{"title":"Judging the Judges: Evaluating Alignment and Vulnerabilities in LLMs-as-Judges","url":"https://aclanthology.org/2025.gem-1.33/","authors":["Aman Singh Thakur","Kartik Choudhary","Venkat Srinik Ramayapally","Sankaran Vaidyanathan","Dieuwke Hupkes"],"year":2025,"abstract":"Evaluates LLM judges against human judgments and analyzes vulnerabilities such as prompt sensitivity and leniency, emphasizing that raw agreement alone is insufficient to establish evaluator validity.","venue":"GEM² 2025"}
{"title":"Judge's Verdict: A Comprehensive Analysis of LLM Judge Capability Through Human Agreement","url":"https://arxiv.org/abs/2510.09738","arxiv_id":"2510.09738","authors":["Steve Han","Gilberto Titericz Junior","Tom Balough","Wenfei Zhou"],"year":2025,"published":"2025-10-10","abstract":"Benchmarks LLM judging against human evaluation and examines agreement using measures beyond simple correlation, including reliability-oriented analyses intended to distinguish apparent scoring similarity from human-like judgment behavior.","venue":"arXiv"}
===END llm_candidates.jsonl===
